61	// runProducer calls producePath synchronously with nobody reading the
62	// channel, failing if it does not return (the channel capacity must hold).
63	func runProducer(t *testing.T, ctx context.Context, gen int, tg pathTarget, rt time.Duration, e pathEngine) []tea.Msg {
64		t.Helper()
65		out := make(chan tea.Msg, pathChanCap)
66		done := make(chan struct{})
67		go func() {
68			defer close(done)
69			producePath(ctx, gen, tg, rt, e, out)
70		}()
71		select {
72		case <-done:
73		case <-time.After(producerWait):
74			t.Fatal("producePath did not return: the producer blocked")
75		}
76		var msgs []tea.Msg
77		for {
78			select {
79			case m, ok := <-out:
80				if !ok {
81					return msgs
82				}
83				msgs = append(msgs, m)
84			default:
85				t.Fatal("channel not closed after producePath returned")
86				return nil
87			}
88		}
