100	func TestProducePathLiteralIPv4SkipsResolve(t *testing.T) {
101		f := &fakeEngine{traceFn: func(_ context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
102			onHop(hopAt(1))
103			onHop(hopAt(2))
104			return nettrace.Result{Target: a, Outcome: nettrace.OutcomeReached, Hops: []nettrace.Hop{hopAt(1), hopAt(2)}}, nil
105		}}
106		msgs := runProducer(t, context.Background(), 7, pathTarget{Host: "1.1.1.1"}, time.Second, f.engine())
107	
108		if f.resolveCalls != 0 {
109			t.Fatalf("resolve called %d times for a literal IPv4", f.resolveCalls)
110		}
111		if f.traceOpts != (nettrace.Options{}) {
112			t.Fatalf("trace options = %+v, want the zero Options", f.traceOpts)
113		}
114		if len(msgs) != 4 {
115			t.Fatalf("got %d messages, want 4 (resolved, 2 hops, done): %#v", len(msgs), msgs)
116		}
117		res, ok := msgs[0].(pathResolvedMsg)
118		if !ok || res.addr != netip.MustParseAddr("1.1.1.1") || res.gen != 7 {
119			t.Fatalf("msgs[0] = %#v, want pathResolvedMsg{7, 1.1.1.1}", msgs[0])
120		}
121		for i, ttl := range []int{1, 2} {
122			h, ok := msgs[1+i].(pathHopMsg)
123			if !ok || h.hop.TTL != ttl || h.gen != 7 {
124				t.Fatalf("msgs[%d] = %#v, want pathHopMsg ttl %d gen 7", 1+i, msgs[1+i], ttl)
125			}
126		}
127		d, ok := msgs[3].(pathDoneMsg)
128		if !ok || d.err != nil || d.gen != 7 || d.result.Outcome != nettrace.OutcomeReached || len(d.result.Hops) != 2 {
129			t.Fatalf("msgs[3] = %#v, want a clean pathDoneMsg", msgs[3])
130		}
131	}
