152	func TestProducePathResolveIsBoundedByTheTimeout(t *testing.T) {
153		const timeout = 40 * time.Millisecond
154		f := &fakeEngine{resolveFn: func(ctx context.Context, _ string) ([]netip.Addr, error) {
155			<-ctx.Done() // blocks until the producer's own deadline fires
156			return nil, ctx.Err()
157		}}
158		start := time.Now()
159		msgs := runProducer(t, context.Background(), 1, pathTarget{Host: "slow.example"}, timeout, f.engine())
160	
161		dl, ok := f.resolveCtx.Deadline()
162		if !ok {
163			t.Fatal("resolve context carries no deadline")
164		}
165		if dl.Sub(start) > timeout+producerWait/2 {
166			t.Fatalf("resolve deadline %v after start, want about %v", dl.Sub(start), timeout)
167		}
168		if len(msgs) != 1 {
169			t.Fatalf("got %d messages, want exactly one done: %#v", len(msgs), msgs)
170		}
171		d, ok := msgs[0].(pathDoneMsg)
172		if !ok || !errors.Is(d.err, errPathResolve) {
173			t.Fatalf("msgs[0] = %#v, want pathDoneMsg wrapping errPathResolve", msgs[0])
