231	func TestProducePathFullTraceNeedsNoReader(t *testing.T) {
232		f := &fakeEngine{traceFn: func(_ context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
