265	func TestProducePathCancelMidTraceReturnsWithoutAReader(t *testing.T) {
266		ctx, cancel := context.WithCancel(context.Background())
267		defer cancel()
268		started := make(chan struct{})
269		f := &fakeEngine{traceFn: func(ctx context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
270			onHop(hopAt(1))
271			close(started)
272			<-ctx.Done() // the engine stops on the context only
273			return nettrace.Result{Target: a, Outcome: nettrace.OutcomeCancelled}, nil
274		}}
275		out := make(chan tea.Msg, pathChanCap)
276		done := make(chan struct{})
277		go func() {
278			defer close(done)
279			producePath(ctx, 1, pathTarget{Host: "10.0.0.6"}, time.Second, f.engine(), out)
280		}()
281	
282		select {
283		case <-started:
284		case <-time.After(producerWait):
285			t.Fatal("trace never started")
286		}
287		cancel() // the view cancels, then stops reading: nobody drains out
288		select {
289		case <-done:
290		case <-time.After(producerWait):
291			t.Fatal("producer goroutine still alive after cancel: leaked or blocked")
292		}
293		var last tea.Msg
294		for m := range out { // closed by the producer, so this terminates
295			last = m
296		}
297		if d, ok := last.(pathDoneMsg); !ok || d.result.Outcome != nettrace.OutcomeCancelled {
298			t.Fatalf("last = %#v, want a done with OutcomeCancelled", last)
299		}
300	}
