302	func TestProducePathEveryMessageCarriesTheGeneration(t *testing.T) {
303		f := &fakeEngine{
304			resolveFn: func(context.Context, string) ([]netip.Addr, error) {
305				return []netip.Addr{netip.MustParseAddr("9.9.9.9")}, nil
306			},
307			traceFn: func(_ context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
308				onHop(hopAt(1))
309				return nettrace.Result{Target: a}, nil
310			},
311		}
312		const gen = 42
313		msgs := runProducer(t, context.Background(), gen, pathTarget{Host: "dns.example"}, time.Second, f.engine())
314	
315		if len(msgs) != 3 {
316			t.Fatalf("got %d messages, want 3: %#v", len(msgs), msgs)
317		}
318		for i, m := range msgs {
319			var got int
320			switch v := m.(type) {
321			case pathResolvedMsg:
322				got = v.gen
323			case pathHopMsg:
324				got = v.gen
325			case pathDoneMsg:
326				got = v.gen
327			default:
328				t.Fatalf("msgs[%d] has unexpected type %T", i, m)
329			}
330			if got != gen {
331				t.Fatalf("msgs[%d].gen = %d, want %d", i, got, gen)
332			}
333		}
