336	func TestWaitForPathMsgReturnsMessagesThenNilOnClose(t *testing.T) {
337		ch := make(chan tea.Msg, 4)
338		ch <- pathResolvedMsg{gen: 1, addr: netip.MustParseAddr("1.1.1.1")}
339		ch <- pathHopMsg{gen: 1, hop: hopAt(1)}
340		close(ch)
341	
342		cmd := waitForPathMsg(ch)
343		if cmd == nil {
344			t.Fatal("waitForPathMsg returned a nil Cmd")
345		}
346		if _, ok := cmd().(pathResolvedMsg); !ok {
347			t.Fatal("first wait should yield the resolved message")
348		}
349		// A fresh Cmd (the re-arm) yields the next one.
350		if _, ok := waitForPathMsg(ch)().(pathHopMsg); !ok {
351			t.Fatal("re-armed wait should yield the hop message")
352		}
353		if got := waitForPathMsg(ch)(); got != nil {
354			t.Fatalf("wait on a closed channel = %#v, want nil", got)
355		}
356	}
