358	func TestWaitForPathMsgBlocksUntilAMessageArrives(t *testing.T) {
359		ch := make(chan tea.Msg, 1)
360		got := make(chan tea.Msg, 1)
361		go func() { got <- waitForPathMsg(ch)() }()
362	
363		select {
364		case m := <-got:
365			t.Fatalf("wait returned %#v before anything was sent", m)
366		case <-time.After(20 * time.Millisecond):
367		}
368		ch <- pathDoneMsg{gen: 5}
369		select {
370		case m := <-got:
371			if d, ok := m.(pathDoneMsg); !ok || d.gen != 5 {
372				t.Fatalf("got %#v, want pathDoneMsg gen 5", m)
373			}
374		case <-time.After(producerWait):
375			t.Fatal("wait did not return after a message was sent")
376		}
